package remediation

import "github.com/anthnel/devdesk/internal/scan"

// STUB (DEVDESK-686, step 2): signatures only, so the red tests compile.

// Profile is a Pod Security Standards profile.
type Profile string

const (
	ProfileBaseline   Profile = "baseline"
	ProfileRestricted Profile = "restricted"
)

// Covers reports whether target requires p: restricted covers baseline.
func (target Profile) Covers(p Profile) bool { return false }

// PSS is the Pod Security profile of a finding. FromTrivy is set when the
// anchor was read in References and the rule is not in the table.
type PSS struct {
	Profile   Profile
	FromTrivy bool
}

// PodSecurity returns the profile that requires the rule behind f.
func PodSecurity(f scan.Finding) (PSS, bool) { return PSS{}, false }

func pssAnchor(refs []string) (Profile, bool) { return "", false }

var pssProfiles = map[string]Profile{}
