		{
			name: "a reference listed twice",
			json: `{"ID":"KSV-0017","PrimaryURL":"` + testAVDKSV17URL + `","References":["` + testPSSBaselineURL + `","` + testPSSBaselineURL + `"]}`,
			want: []string{testAVDKSV17URL, testPSSBaselineURL},
