func TestTrivyMisconfigWithoutReferencesKeepsPrimaryURL(t *testing.T) {
	f := parseOneMisconfig(t, `{"ID":"DS002","Severity":"HIGH","PrimaryURL":"https://avd.aquasec.com/misconfig/ds002"}`)
