		{"KSV-0003 is not Pod Security", pssFinding("KSV-0003"), PSS{}, false},
		{"AVD-KSV-0017 spelling", avdSpelling, PSS{Profile: ProfileBaseline}, true},
		{"KSV017 spelling", shortSpelling, PSS{Profile: ProfileBaseline}, true},
