// path is not there.
func follow(n *yaml.Node, keys []string) *yaml.Node {
	for _, key := range keys {
		if n == nil {
			return nil
		}
		_, v, ok := Entry(n, key)
		if !ok {
			return nil
		}
		n = v
	}
	return n
}
